SELECT YEAR_MONTH ym, PRACTICE_CODE pc, max(PRACTICE_NAME) pn, max(ICB_NAME) icb,
  sum(ITEMS) all_items,
  sum(CASE WHEN BNF_CHEMICAL_SUBSTANCE_CODE IN ('0501012G0','0501013B0','0501130R0','0501030I0','0501011P0','0501080W0','0501021L0','0501110C0','0501015P0','0501080D0','0501070AE','0501030Z0','0501030V0','0501021M0','0501040H0','0501021B0','0501011J0','0501013E0','0501013C0','0501130S0','0501110G0','0501013L0','0501012H0') THEN ITEMS ELSE 0 END) access_items,
  sum(CASE WHEN BNF_CHEMICAL_SUBSTANCE_CODE IN ('0501050B0','0501013K0','0501050A0','0501030L0','0501120L0','0501050C0','0501030T0','0501050H0','0501060D0','0501120P0','0501120X0','0501070U0','0501050N0','0501030P0','0501120Y0','0501021K0','0501070AC','0501021A0','0501040U0','0501021G0','0501070T0','0501021H0','0501021C0','0501070N0','0501021J0','0501021D0','0501070M0','0501040N0','0501014S0','0501040C0','0501070F0','0501120Q0','0501060E0','0501050K0','0501021E0') THEN ITEMS ELSE 0 END) watch_items,
  sum(CASE WHEN BNF_CHEMICAL_SUBSTANCE_CODE IN ('0501070W0','0501022B0','0501070AF','0501022A0') THEN ITEMS ELSE 0 END) reserve_items,
  sum(CASE WHEN BNF_CHEMICAL_SUBSTANCE_CODE IN ('0501130H0','0501030F0','0501080J0','0501080V0','0501070Z0') THEN ITEMS ELSE 0 END) other_items,
  sum(CASE WHEN BNF_CHEMICAL_SUBSTANCE_CODE='0501030L0' THEN ITEMS ELSE 0 END) lyme_items
FROM `EPD_SNOMED_202607`
WHERE BNF_PRESENTATION_CODE LIKE '0501%' AND UNIDENTIFIED <> 'Y'
GROUP BY YEAR_MONTH, PRACTICE_CODE
